def get_shipping_quote(order: Order) -> int:
    if not order.zip:
        raise ValueError("zip required")
    payload = {"zip": order.zip, "weight_g": order.weight_g}
    resp = requests.post(f"{CARRIER_URL}/quotes", json=payload)
    resp.raise_for_status()
    quote = resp.json()
    log.info("quote for %s: %s", order.id, quote["price_cents"])
    return quote["price_cents"]

